try {
  helpers.log('WhatsApp - Send Template: Starting');

  const accessToken = node.properties.credential.value;
  const phoneNumberId = node.properties.phoneNumberId.value;
  const to = node.properties.recipientPhone.value;
  const templateName = node.properties.templateName.value;
  const language = node.properties.language.value || 'en_US';
  const parametersStr = node.properties.parameters.value;

  let components = [];
  if (parametersStr) {
    try {
      const params = JSON.parse(parametersStr);
      if (Array.isArray(params) && params.length > 0) {
        components = [{
          type: 'body',
          parameters: params.map(p => ({ type: 'text', text: String(p) }))
        }];
      }
    } catch (e) {
      helpers.warn('Invalid parameters JSON, sending without parameters');
    }
  }

  const endpoint = `https://graph.facebook.com/v18.0/${phoneNumberId}/messages`;
  const payload = {
    messaging_product: 'whatsapp',
    to: to,
    type: 'template',
    template: {
      name: templateName,
      language: { code: language },
      components: components
    }
  };

  helpers.log('Sending template:', templateName);

  const response = await fetch(endpoint, {
    method: 'POST',
    headers: {
      'Authorization': `Bearer ${accessToken}`,
      'Content-Type': 'application/json'
    },
    body: JSON.stringify(payload)
  });

  const result = await response.json();

  if (!response.ok) {
    helpers.error('API Error:', result.error?.message);
    throw new Error(`WhatsApp API Error: ${result.error?.message || 'Unknown'}`);
  }

  helpers.log('Template sent. Message ID:', result.messages?.[0]?.id);

  return { ...data, messageId: result.messages?.[0]?.id, whatsapp: result };

} catch (error) {
  helpers.error('Failed:', error.message);
  throw error;
}
